"""Pages of shipments."""


def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size


def page(shipments, number, page_size):
    """Return page `number` of shipments. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return shipments[start:start + page_size]


def all_pages(shipments, page_size):
    """Return every page of shipments, in order."""
    return [page(shipments, n, page_size) for n in range(1, page_count(len(shipments), page_size) + 1)]


def describe_shipment(shipment):
    """Return a one-line description of a shipment."""
    return "%s: %s" % (shipment.route, shipment.weight)


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups

